import fs from 'node:fs';
import path from 'node:path';
import {fileURLToPath} from 'node:url';

const DEFAULT_EVENT = 'message';
const DONE_MARKER = '[DONE]';

// Canonical standard padded base64, exactly as produced by Buffer.toString('base64').
// The trailing groups constrain the pad bits so noncanonical encodings are rejected.
const BASE64_RE =
  /^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}[AQgw]==|[A-Za-z0-9+/]{3}[AEIMQUYcgkosw048]=)?$/;

function fail(message) {
  throw new Error(message);
}

/**
 * Transport-independent decoder. Chunk boundaries carry no meaning: multibyte
 * UTF-8 sequences, CRLF pairs, lines and frames may all straddle pushes.
 */
export function createDecoder() {
  // Streaming UTF-8 decoder. fatal:true rejects invalid sequences; leaving
  // ignoreBOM false makes it drop exactly one leading BOM.
  const utf8 = new TextDecoder('utf-8', {fatal: true, ignoreBOM: false});

  let pending = ''; // decoded text not yet consumed as a complete line
  let dataParts = null; // null until this frame has at least one data field
  let lastEvent = null; // last event-field value seen in this frame
  let terminated = false; // a [DONE] frame has been dispatched
  let finished = false;
  let poisoned = false;

  function resetFrame() {
    dataParts = null;
    lastEvent = null;
  }

  function decode(chunk, stream) {
    try {
      return utf8.decode(chunk, {stream});
    } catch {
      return fail('invalid UTF-8 in stream');
    }
  }

  // Returns a frame object when the line completes a dispatchable frame.
  function handleLine(line) {
    if (terminated) {
      if (line !== '') fail('unexpected line after termination marker');
      return null;
    }
    if (line === '') {
      const parts = dataParts;
      const event = lastEvent;
      resetFrame();
      if (parts === null) return null; // no data field: nothing to dispatch
      const data = parts.join('\n');
      if (data === DONE_MARKER) {
        terminated = true;
        return null;
      }
      return {event: event === null || event === '' ? DEFAULT_EVENT : event, data};
    }
    if (line.startsWith(':')) return null; // comment

    const colon = line.indexOf(':');
    let field, value;
    if (colon === -1) {
      field = line;
      value = '';
    } else {
      field = line.slice(0, colon);
      value = line.slice(colon + 1);
      if (value.startsWith(' ')) value = value.slice(1);
    }
    if (field === 'data') {
      if (dataParts === null) dataParts = [];
      dataParts.push(value);
    } else if (field === 'event') {
      lastEvent = value;
    }
    return null;
  }

  function guard() {
    if (poisoned) fail('decoder is unusable after a previous failure');
    if (finished) fail('decoder already finished');
  }

  return {
    push(chunk) {
      try {
        guard();
        if (!(chunk instanceof Uint8Array)) fail('push requires a Uint8Array chunk');
        pending += decode(chunk, true);

        const frames = [];
        let start = 0;
        for (;;) {
          const lf = pending.indexOf('\n', start);
          if (lf === -1) break;
          let end = lf;
          if (end > start && pending.charCodeAt(end - 1) === 13) end -= 1; // one CR before LF
          const frame = handleLine(pending.slice(start, end));
          if (frame !== null) frames.push(frame);
          start = lf + 1;
        }
        if (start > 0) pending = pending.slice(start);
        return frames;
      } catch (error) {
        poisoned = true;
        throw error;
      }
    },

    finish() {
      try {
        guard();
        decode(undefined, false); // flushes: throws on a truncated multibyte sequence
        if (pending !== '') fail('stream ended with an unterminated line');
        if (dataParts !== null || lastEvent !== null) fail('stream ended with a pending frame');
        if (!terminated) fail('stream ended without a termination marker');
        finished = true;
        return [];
      } catch (error) {
        poisoned = true;
        throw error;
      }
    },
  };
}

function decodeUtf8Strict(buffer, what) {
  try {
    return new TextDecoder('utf-8', {fatal: true}).decode(buffer);
  } catch {
    return fail(`${what} is not valid UTF-8`);
  }
}

function runCli(argv) {
  if (argv.length !== 1) fail('usage: stream-framer.js INPUT_JSON_FILE');

  let raw;
  try {
    raw = fs.readFileSync(argv[0]);
  } catch (error) {
    return fail(`cannot read input file: ${error.message}`);
  }

  let input;
  try {
    input = JSON.parse(decodeUtf8Strict(raw, 'input file'));
  } catch (error) {
    return fail(`invalid input JSON: ${error.message}`);
  }
  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
    fail('input must be a JSON object');
  }
  if (!Array.isArray(input.chunks)) fail('input.chunks must be an array');

  const chunks = input.chunks.map((encoded, index) => {
    if (typeof encoded !== 'string') fail(`chunks[${index}] must be a string`);
    if (!BASE64_RE.test(encoded)) fail(`chunks[${index}] is not canonical padded base64`);
    return Buffer.from(encoded, 'base64');
  });

  const decoder = createDecoder();
  const frames = [];
  for (const chunk of chunks) frames.push(...decoder.push(chunk));
  frames.push(...decoder.finish());
  return JSON.stringify({frames}) + '\n';
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  try {
    process.stdout.write(runCli(process.argv.slice(2)));
  } catch (error) {
    process.stderr.write(`${(error && error.message) || 'stream-framer failed'}\n`);
    process.exitCode = 2;
  }
}

import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {execFileSync, execFileSync as run} from 'node:child_process';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createDecoder} from '../stream-framer.js';

const CLI = fileURLToPath(new URL('../stream-framer.js', import.meta.url));

const b = (s) => Buffer.from(s, 'utf8');
const drain = (d, bytes) => {
  const out = [];
  for (const byte of bytes) out.push(...d.push(Uint8Array.of(byte)));
  return out;
};

test('byte-at-a-time equals all-at-once', () => {
  const src = b(
    ':comment\nevent: a\nevent:\ndata: x\r\ndata:\n\n:c\n\nevent: keep\n\ndata: y\n\ndata: [DONE]\n\n',
  );
  const whole = createDecoder();
  const a1 = whole.push(src);
  assert.deepEqual(whole.finish(), []);
  const single = createDecoder();
  const a2 = drain(single, src);
  assert.deepEqual(single.finish(), []);
  assert.deepEqual(a1, [
    {event: 'message', data: 'x\n'},
    {event: 'message', data: 'y'},
  ]);
  assert.deepEqual(a2, a1);
});

test('event name never leaks past a frame boundary', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('event: one\ndata: a\n\ndata: b\n\ndata: [DONE]\n\n')), [
    {event: 'one', data: 'a'},
    {event: 'message', data: 'b'},
  ]);
  d.finish();
});

test('no-colon field lines and unknown fields', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('id: 7\nretry\ndata\n\ndata:  sp\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: ''},
    {event: 'message', data: ' sp'},
  ]);
  d.finish();
});

test('lone CR stays data, CRLF splits across chunks', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('data: a\rb\r')), []);
  assert.deepEqual(d.push(b('\n\r\n')), [{event: 'message', data: 'a\rb'}]);
  assert.deepEqual(d.push(b('data: [DONE]\r\n\r\n')), []);
  d.finish();
});

test('leading BOM ignored once, later BOMs are data', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('﻿data: ﻿x\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: '﻿x'},
  ]);
  d.finish();
});

test('[DONE] with an event name still terminates silently', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('event: done\ndata: [DONE]\n\n')), []);
  assert.deepEqual(d.push(b('\n\n')), []);
  assert.deepEqual(d.finish(), []);
});

test('multiline data joining [DONE] is a literal frame', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('data: [DONE]\ndata: x\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: '[DONE]\nx'},
  ]);
  d.finish();
});

test('post-termination nonblank lines throw and poison', () => {
  for (const tail of ['data: [DONE]\n\n', ':c\n', 'x\n', 'data: a\n']) {
    const d = createDecoder();
    d.push(b('data: [DONE]\n\n'));
    assert.throws(() => d.push(b(tail)), Error);
    assert.throws(() => d.push(new Uint8Array()), Error);
    assert.throws(() => d.finish(), Error);
  }
});

test('unterminated final line and pending fields fail finish', () => {
  const a = createDecoder();
  a.push(b('data: [DONE]\n\ndata: x'));
  assert.throws(() => a.finish(), Error);
  const c = createDecoder();
  c.push(b('data: a\n'));
  assert.throws(() => c.finish(), Error);
});

test('invalid UTF-8 and truncated sequences throw', () => {
  const d = createDecoder();
  assert.throws(() => d.push(Uint8Array.of(0xff)), Error);
  const e = createDecoder();
  e.push(b('data: [DONE]\n\n'));
  e.push(Uint8Array.of(0xe9));
  assert.throws(() => e.finish(), Error);
});

test('non-Uint8Array chunks rejected and poison the decoder', () => {
  for (const bad of ['data: a\n', 42, null, undefined, [1, 2], new ArrayBuffer(2)]) {
    const d = createDecoder();
    assert.throws(() => d.push(bad), Error);
    assert.throws(() => d.push(new Uint8Array()), Error);
  }
});

test('chunks are not mutated and decoders are independent', () => {
  const chunk = b('data: hi\n\ndata: [DONE]\n\n');
  const copy = Buffer.from(chunk);
  const good = createDecoder();
  const bad = createDecoder();
  assert.throws(() => bad.push('nope'), Error);
  assert.deepEqual(good.push(chunk), [{event: 'message', data: 'hi'}]);
  assert.deepEqual(good.finish(), []);
  assert.deepEqual(chunk, copy);
});

function cli(args, contents) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'framer-'));
  try {
    const file = path.join(dir, 'input.json');
    if (contents !== undefined) fs.writeFileSync(file, contents);
    return spawnSync(process.execPath, [CLI, ...args.map((a) => (a === '@' ? file : a))], {
      encoding: 'utf8',
    });
  } finally {
    fs.rmSync(dir, {recursive: true, force: true});
  }
}

test('CLI success prints one JSON value and nothing on stderr', () => {
  const chunks = [b('data: hi\n'), b('\ndata: [DONE]'), b('\n\n')].map((x) =>
    x.toString('base64'),
  );
  const r = cli(['@'], JSON.stringify({chunks, ignored: 1}));
  assert.equal(r.status, 0);
  assert.equal(r.stderr, '');
  assert.equal(r.stdout, JSON.stringify({frames: [{event: 'message', data: 'hi'}]}) + '\n');
});

test('CLI rejects bad arguments, files, JSON, base64 and protocol', () => {
  const cases = [
    [[], undefined],
    [['@', '@'], '{"chunks":[]}'],
    [['@'], undefined],
    [['@'], 'not json'],
    [['@'], '[]'],
    [['@'], 'null'],
    [['@'], '{"chunks":{}}'],
    [['@'], '{"chunks":[1]}'],
    [['@'], '{"chunks":["a"]}'],
    [['@'], '{"chunks":["_w=="]}'],
    [['@'], '{"chunks":["AA =="]}'],
    [['@'], '{"chunks":["AB=="]}'],
    [['@'], `{"chunks":["${b('data: hi\n\n').toString('base64')}"]}`],
  ];
  for (const [args, contents] of cases) {
    const r = cli(args, contents);
    assert.equal(r.status, 2, JSON.stringify([args, contents]));
    assert.equal(r.stdout, '');
    assert.ok(r.stderr.length > 0);
  }
});

test('CLI accepts empty base64 strings', () => {
  const r = cli(['@'], JSON.stringify({chunks: ['', b('data: [DONE]\n\n').toString('base64'), '']}));
  assert.equal(r.status, 0);
  assert.equal(r.stdout, '{"frames":[]}\n');
});

test('importing the module does not run the CLI', () => {
  const r = spawnSync(
    process.execPath,
    ['--input-type=module', '-e', `import(${JSON.stringify(CLI)}).then(m=>process.stdout.write(typeof m.createDecoder))`],
    {encoding: 'utf8'},
  );
  assert.equal(r.status, 0);
  assert.equal(r.stdout, 'function');
  assert.equal(r.stderr, '');
});

