import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {spawnSync} from 'node:child_process';
import {fileURLToPath} from 'node:url';
import {createDecoder} from '../stream-framer.js';

const CLI = fileURLToPath(new URL('../stream-framer.js', import.meta.url));

const b = (s) => Buffer.from(s, 'utf8');
const drain = (d, bytes) => {
  const out = [];
  for (const byte of bytes) out.push(...d.push(Uint8Array.of(byte)));
  return out;
};

test('byte-at-a-time equals all-at-once', () => {
  const src = b(
    ':comment\nevent: a\nevent:\ndata: x\r\ndata:\n\n:c\n\nevent: keep\n\ndata: y\n\ndata: [DONE]\n\n',
  );
  const whole = createDecoder();
  const a1 = whole.push(src);
  assert.deepEqual(whole.finish(), []);
  const single = createDecoder();
  const a2 = drain(single, src);
  assert.deepEqual(single.finish(), []);
  assert.deepEqual(a1, [
    {event: 'message', data: 'x\n'},
    {event: 'message', data: 'y'},
  ]);
  assert.deepEqual(a2, a1);
});

test('event name never leaks past a frame boundary', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('event: one\ndata: a\n\ndata: b\n\ndata: [DONE]\n\n')), [
    {event: 'one', data: 'a'},
    {event: 'message', data: 'b'},
  ]);
  d.finish();
});

test('no-colon field lines and unknown fields', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('id: 7\nretry\ndata\n\ndata:  sp\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: ''},
    {event: 'message', data: ' sp'},
  ]);
  d.finish();
});

test('lone CR stays data, CRLF splits across chunks', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('data: a\rb\r')), []);
  assert.deepEqual(d.push(b('\n\r\n')), [{event: 'message', data: 'a\rb'}]);
  assert.deepEqual(d.push(b('data: [DONE]\r\n\r\n')), []);
  d.finish();
});

test('leading BOM ignored once, later BOMs are data', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('﻿data: ﻿x\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: '﻿x'},
  ]);
  d.finish();
});

test('[DONE] with an event name still terminates silently', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('event: done\ndata: [DONE]\n\n')), []);
  assert.deepEqual(d.push(b('\n\n')), []);
  assert.deepEqual(d.finish(), []);
});

test('multiline data joining [DONE] is a literal frame', () => {
  const d = createDecoder();
  assert.deepEqual(d.push(b('data: [DONE]\ndata: x\n\ndata: [DONE]\n\n')), [
    {event: 'message', data: '[DONE]\nx'},
  ]);
  d.finish();
});

test('post-termination nonblank lines throw and poison', () => {
  for (const tail of ['data: [DONE]\n\n', ':c\n', 'x\n', 'data: a\n']) {
    const d = createDecoder();
    d.push(b('data: [DONE]\n\n'));
    assert.throws(() => d.push(b(tail)), Error);
    assert.throws(() => d.push(new Uint8Array()), Error);
    assert.throws(() => d.finish(), Error);
  }
});

test('unterminated final line and pending fields fail finish', () => {
  const a = createDecoder();
  a.push(b('data: [DONE]\n\ndata: x'));
  assert.throws(() => a.finish(), Error);
  const c = createDecoder();
  c.push(b('data: a\n'));
  assert.throws(() => c.finish(), Error);
});

test('invalid UTF-8 and truncated sequences throw', () => {
  const d = createDecoder();
  assert.throws(() => d.push(Uint8Array.of(0xff)), Error);
  const e = createDecoder();
  e.push(b('data: [DONE]\n\n'));
  e.push(Uint8Array.of(0xe9));
  assert.throws(() => e.finish(), Error);
});

test('non-Uint8Array chunks rejected and poison the decoder', () => {
  for (const bad of ['data: a\n', 42, null, undefined, [1, 2], new ArrayBuffer(2)]) {
    const d = createDecoder();
    assert.throws(() => d.push(bad), Error);
    assert.throws(() => d.push(new Uint8Array()), Error);
  }
});

test('chunks are not mutated and decoders are independent', () => {
  const chunk = b('data: hi\n\ndata: [DONE]\n\n');
  const copy = Buffer.from(chunk);
  const good = createDecoder();
  const bad = createDecoder();
  assert.throws(() => bad.push('nope'), Error);
  assert.deepEqual(good.push(chunk), [{event: 'message', data: 'hi'}]);
  assert.deepEqual(good.finish(), []);
  assert.deepEqual(chunk, copy);
});

function cli(args, contents) {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'framer-'));
  try {
    const file = path.join(dir, 'input.json');
    if (contents !== undefined) fs.writeFileSync(file, contents);
    return spawnSync(process.execPath, [CLI, ...args.map((a) => (a === '@' ? file : a))], {
      encoding: 'utf8',
    });
  } finally {
    fs.rmSync(dir, {recursive: true, force: true});
  }
}

test('CLI success prints one JSON value and nothing on stderr', () => {
  const chunks = [b('data: hi\n'), b('\ndata: [DONE]'), b('\n\n')].map((x) =>
    x.toString('base64'),
  );
  const r = cli(['@'], JSON.stringify({chunks, ignored: 1}));
  assert.equal(r.status, 0);
  assert.equal(r.stderr, '');
  assert.equal(r.stdout, JSON.stringify({frames: [{event: 'message', data: 'hi'}]}) + '\n');
});

test('CLI rejects bad arguments, files, JSON, base64 and protocol', () => {
  const cases = [
    [[], undefined],
    [['@', '@'], '{"chunks":[]}'],
    [['@'], undefined],
    [['@'], 'not json'],
    [['@'], '[]'],
    [['@'], 'null'],
    [['@'], '{"chunks":{}}'],
    [['@'], '{"chunks":[1]}'],
    [['@'], '{"chunks":["a"]}'],
    [['@'], '{"chunks":["_w=="]}'],
    [['@'], '{"chunks":["AA =="]}'],
    [['@'], '{"chunks":["AB=="]}'],
    [['@'], `{"chunks":["${b('data: hi\n\n').toString('base64')}"]}`],
  ];
  for (const [args, contents] of cases) {
    const r = cli(args, contents);
    assert.equal(r.status, 2, JSON.stringify([args, contents]));
    assert.equal(r.stdout, '');
    assert.ok(r.stderr.length > 0);
  }
});

test('CLI accepts empty base64 strings', () => {
  const r = cli(['@'], JSON.stringify({chunks: ['', b('data: [DONE]\n\n').toString('base64'), '']}));
  assert.equal(r.status, 0);
  assert.equal(r.stdout, '{"frames":[]}\n');
});

test('importing the module does not run the CLI', () => {
  const r = spawnSync(
    process.execPath,
    ['--input-type=module', '-e', `import(${JSON.stringify(CLI)}).then(m=>process.stdout.write(typeof m.createDecoder))`],
    {encoding: 'utf8'},
  );
  assert.equal(r.status, 0);
  assert.equal(r.stdout, 'function');
  assert.equal(r.stderr, '');
});

